
  /* ============================================================
     LES MASCOTTES — quatre figures algériennes, articulées
       fennec   : l'emblème (Les Fennecs), compagnon principal
       chameau  : les wilayas du Sud
       cigogne  : l'Est, la cigogne de Constantine
       palmier  : les oasis

     Chaque personnage est livré en DEUX pièces, tête et corps,
     coupées au niveau de l'écharpe. C'est ce qui permet une vraie
     animation articulée : la tête s'incline et acquiesce sur un
     corps qui respire, au lieu d'une image entière qu'on déforme.
     L'écharpe recouvre la couture, et la tête déborde sous la
     coupe pour qu'aucun trou n'apparaisse au cou en tournant.

     px / py : l'axe de rotation de la tête, en fraction du cadre.
     w / h   : le format de la pièce, pour empiler les deux calques.

     Intégrées en base64 : l'APK est hors ligne et l'artifact bloque
     les hôtes externes — une URL ne chargerait jamais.
     ============================================================ */
  var MASCOTS = {
    fennec: { w:237, h:340, px:0.440, py:0.620,
      body:"data:image/webp;base64,",
      head:"data:image/webp;base64," },
    chameau: { w:291, h:340, px:0.520, py:0.490,
      body:"data:image/webp;base64,",
      head:"data:image/webp;base64," },
    cigogne: { w:218, h:340, px:0.460, py:0.480,
      body:"data:image/webp;base64,",
      head:"data:image/webp;base64," },
    palmier: { w:292, h:340, px:0.480, py:0.640,
      body:"data:image/webp;base64,",
      head:"data:image/webp;base64," }
  };
